BEGIN;
CREATE TYPE semantic_status AS ENUM ('UNPARSED','PARSED','VALID','AMBIGUOUS','CONFLICTING','UNSUPPORTED','STALE','INVALIDATED');
CREATE TYPE payout_model AS ENUM ('SIMPLE_BINARY','SCALAR_OR_PARTIAL','MULTIVARIATE','UNKNOWN','UNSUPPORTED');
CREATE TABLE contract_specifications (contract_spec_id uuid PRIMARY KEY, market_ticker text NOT NULL REFERENCES markets(ticker), event_ticker text NOT NULL REFERENCES events(ticker), series_ticker text NOT NULL REFERENCES series(ticker), rules_version_id text NOT NULL, metadata_version_id text NOT NULL, yes_proposition text NOT NULL, no_proposition text NOT NULL, settlement_type text NOT NULL, payout_model payout_model NOT NULL, measured_event_or_value text NOT NULL, subject_entities jsonb NOT NULL, geographic_scope text, comparator text NOT NULL, threshold_value numeric, threshold_unit text, lower_bound numeric, upper_bound numeric, inclusivity text, measurement_window_start timestamptz, measurement_window_end timestamptz, deadline timestamptz, timezone text, occurrence_time timestamptz, expected_expiration timestamptz, actual_expiration timestamptz, settlement_authority text, source_precedence_status text NOT NULL, rounding_rules text, revision_rules text, correction_rules text, recount_rules text, cancellation_rules text, postponement_rules text, early_close_rules text, exception_rules jsonb NOT NULL, strike_type text, functional_strike text, custom_strike text, ambiguities jsonb NOT NULL, contradictions jsonb NOT NULL, unsupported_features jsonb NOT NULL, semantic_confidence numeric NOT NULL, semantic_status semantic_status NOT NULL, deterministic_parser_version text NOT NULL, llm_parser_version text, source_input_hash text NOT NULL, semantic_hash text NOT NULL, created_at timestamptz NOT NULL, supersedes_spec_id uuid REFERENCES contract_specifications(contract_spec_id), UNIQUE(market_ticker,source_input_hash));
CREATE TABLE contract_semantic_versions (market_ticker text NOT NULL, version integer NOT NULL, contract_spec_id uuid NOT NULL REFERENCES contract_specifications(contract_spec_id), semantic_hash text NOT NULL, status semantic_status NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz, PRIMARY KEY(market_ticker,version));
CREATE TABLE semantic_field_provenance (contract_spec_id uuid REFERENCES contract_specifications(contract_spec_id), field_name text NOT NULL, source_layer text NOT NULL, source_field text NOT NULL, source_document_id text, source_locator text, original_value text NOT NULL, parser text NOT NULL, parser_version text NOT NULL, PRIMARY KEY(contract_spec_id,field_name,source_layer,source_field));
CREATE TABLE semantic_issues (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, contract_spec_id uuid REFERENCES contract_specifications(contract_spec_id), issue_type text NOT NULL, severity text NOT NULL, fields jsonb NOT NULL, description text NOT NULL, source_references jsonb NOT NULL, blocking boolean NOT NULL, detected_at timestamptz NOT NULL, resolved_at timestamptz);
CREATE TABLE settlement_source_registry (source_id text PRIMARY KEY, normalized_name text NOT NULL, exchange_name text NOT NULL, url text, origin_layer text NOT NULL, classification text NOT NULL, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, current boolean NOT NULL, source_hash text NOT NULL UNIQUE);
CREATE TABLE settlement_source_links (contract_spec_id uuid REFERENCES contract_specifications(contract_spec_id), source_id text REFERENCES settlement_source_registry(source_id), precedence_status text NOT NULL, PRIMARY KEY(contract_spec_id,source_id));
CREATE TABLE contract_document_versions (document_id text PRIMARY KEY, url text NOT NULL, retrieved_at timestamptz NOT NULL, content_type text NOT NULL, content_hash text NOT NULL, object_key text NOT NULL, supersedes_document_id text REFERENCES contract_document_versions(document_id), UNIQUE(url,content_hash));
CREATE TABLE semantic_validation_runs (run_id uuid PRIMARY KEY, market_ticker text NOT NULL, source_input_hash text NOT NULL, parser_versions jsonb NOT NULL, started_at timestamptz NOT NULL, completed_at timestamptz, status semantic_status NOT NULL, issue_count integer NOT NULL);
CREATE TABLE semantic_invalidations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, contract_spec_id uuid REFERENCES contract_specifications(contract_spec_id), cause text NOT NULL, source_hash text, invalidated_at timestamptz NOT NULL);
CREATE TABLE settlement_observations (observation_id text PRIMARY KEY, market_ticker text NOT NULL, source_id text REFERENCES settlement_source_registry(source_id), value_text text NOT NULL, published_at timestamptz NOT NULL, observed_at timestamptz NOT NULL, content_hash text NOT NULL, is_correction boolean NOT NULL, supersedes_observation_id text REFERENCES settlement_observations(observation_id));
CREATE TABLE exchange_determinations (determination_id text PRIMARY KEY, market_ticker text NOT NULL, state text NOT NULL, result text, settlement_value_dollars numeric, exchange_at timestamptz NOT NULL, received_at timestamptz NOT NULL, raw_hash text NOT NULL, supersedes_determination_id text REFERENCES exchange_determinations(determination_id));
CREATE TABLE settlement_records (market_ticker text NOT NULL, rules_version text NOT NULL, semantic_spec_id uuid REFERENCES contract_specifications(contract_spec_id), result text NOT NULL, settlement_value_dollars numeric NOT NULL, determined_at timestamptz NOT NULL, finalized_at timestamptz, exchange_record_hash text NOT NULL, source_observation_id text REFERENCES settlement_observations(observation_id), reconciliation_status text NOT NULL, PRIMARY KEY(market_ticker,exchange_record_hash));
CREATE INDEX contract_specs_status_idx ON contract_specifications(semantic_status,payout_model);
CREATE INDEX semantic_issues_open_idx ON semantic_issues(issue_type) WHERE resolved_at IS NULL;
COMMIT;
